let route=projectRoute(location.href);
let STORAGE_KEY=route?BASE_STORAGE_KEY+':'+route.key:BASE_STORAGE_KEY;
if(route?.id==='phygital')for(const p of CATALOG)if(PHYGITAL_REFERENCE[p.id])Object.assign(p,PHYGITAL_REFERENCE[p.id]);
let state=route?(route.id==='phygital'?phygitalTemplate(route.variant):route.generated?emptyProject():exampleTemplate(route.id)):emptyProject(),restoreMessage='';
