try{const saved=localStorage.getItem(STORAGE_KEY);if(saved){state=validateState(JSON.parse(saved));if(upgradeWatchBattery(state))localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}}catch{restoreMessage='Saved project could not be read. A fresh workspace is open.';}
