function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function persist(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));$('#saved-label').textContent='Saved';}catch{$('#saved-label').textContent='Storage unavailable · export your work';}}
function mutate(fn){if(building){toast('Finish or stop the build before editing.');return;}history.push(clone(state));history=history.slice(-60);future=[];fn();persist();render();document.dispatchEvent(new Event('phygital:state'));}
function undo(){if(building)return;if(!history.length)return;future.push(clone(state));state=history.pop();persist();render();toast('Change undone');}
function redo(){if(building)return;if(!future.length)return;history.push(clone(state));state=future.pop();persist();render();}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let guideCleanup;
