function cableDialog(existing,from='',to=''){
 const c=existing?clone(existing):{id:crypto.randomUUID(),from,to,type:'Hook-up wire',bundle:'New cable',length:100,color:'#47a6a0',status:'Planned',note:''};
 const options=value=>allParts().filter(p=>active(p.id)||[c.from.split(':')[0],c.to.split(':')[0]].includes(p.id)).map(p=>`<optgroup label="${esc(p.short)}">${portsFor(state,p.id).map(q=>`<option value="${p.id}:${q.id}" ${value===p.id+':'+q.id?'selected':''}>${esc(q.group)} · ${esc(q.label)}</option>`).join('')}</optgroup>`).join('');
 showDialog(existing?'Edit connection':'Add connection',`<form id="cable-form"><div class="two-fields"><label>From<select id="cable-from" required><option value="">Select contact</option>${options(c.from)}</select></label><label>To<select id="cable-to" required><option value="">Select contact</option>${options(c.to)}</select></label></div><div class="two-fields"><label>Cable type<select id="cable-type">${CABLE_TYPES.map(t=>`<option ${c.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Harness / cable name<input id="cable-bundle" maxlength="100" value="${esc(c.bundle)}" required></label></div><div class="three-fields"><label>Length · mm<input id="cable-length" type="number" min="0" max="5000" value="${c.length}" required></label><label>Wire color (record only)<input id="cable-color" type="color" value="${c.color}"></label><label>Status<select id="cable-status"><option ${c.status==='Planned'?'selected':''}>Planned</option><option ${c.status==='Bench checked'?'selected':''}>Bench checked</option></select></label></div><label>Pinout / routing notes<textarea id="cable-note" rows="3" maxlength="4000">${esc(c.note)}</textarea></label><div id="cable-checks" class="cable-checks"></div><div class="dialog-actions">${existing?'<button type="button" class="button danger" id="delete-cable">Remove connection</button>':''}<button class="button primary" type="submit">Save connection</button></div></form>`);
 const read=()=>({...c,from:$('#cable-from').value,to:$('#cable-to').value,type:$('#cable-type').value,bundle:$('#cable-bundle').value,length:+$('#cable-length').value,color:$('#cable-color').value,status:$('#cable-status').value,note:$('#cable-note').value});
 const update=()=>{$('#cable-checks').innerHTML=connectionIssues(state,read()).map(t=>`<p>${esc(t)}</p>`).join('')||'<p>No basic mismatch found. This does not certify the circuit.</p>';};$$('#cable-form input,#cable-form select').forEach(el=>el.addEventListener('input',update));update();
 $('#cable-form').onsubmit=e=>{e.preventDefault();const next=read();if(next.from===next.to){toast('Choose two different contacts.');return;}if((state.connections||[]).some(x=>x.id!==next.id&&((x.from===next.from&&x.to===next.to)||(x.from===next.to&&x.to===next.from)))){toast('Those contacts already have a connection. Edit the existing one.');return;}mutate(()=>{state.connections=(state.connections||[]).filter(x=>x.id!==next.id);state.connections.push(next);});$('#dialog').close();toast('Connections saved');};
 $('#delete-cable')?.addEventListener('click',()=>{mutate(()=>state.connections=state.connections.filter(x=>x.id!==c.id));$('#dialog').close();});
}
function addContactDialog(){
 showDialog('Add a contact',`<form id="contact-form"><label>Contact label<input name="label" maxlength="100" required placeholder="e.g. SDA / pin 3"></label><div class="two-fields"><label>Function<select name="signal">${['unknown','sda','scl','ground','power','gpio','analog','rf','motor','tx','rx','usb'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Voltage rail<select name="rail"><option value="unknown">Unknown</option><option value="0">Ground</option><option>3.3</option><option>5</option><option value="cell">Battery cell</option></select></label></div><label>Connector group<input name="group" maxlength="150" placeholder="e.g. J1 / I²C header"></label><label>Location on component<select name="location"><option value="-1,0,0">Left edge</option><option value="1,0,0">Right edge</option><option value="0,0,-1">Front edge</option><option value="0,0,1">Back edge</option><option value="0,1,0">Top face</option><option value="0,-1,0">Bottom face</option></select></label><p class="hint">Use the actual pinout. Diagram positions are approximate.</p><button class="button primary full">Add contact</button></form>`);
 $('#contact-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if((partFor(state,selected).ports||[]).length>=40){toast('Maximum 40 custom contacts per part.');return;}mutate(()=>{const p=partFor(state,selected);p.ports||=[];p.ports.push({id:'p'+crypto.randomUUID(),label:f.get('label').trim(),signal:f.get('signal'),group:f.get('group').trim()||'Custom contacts',anchor:f.get('location').split(',').map(Number),rail:f.get('signal')==='ground'?'0':f.get('rail')});});$('#dialog').close();};
}

function checkCard(c){return `<article class="check-card ${c.level}"><span class="check-icon">${icon(c.level==='ok'?'circle-check':c.level==='warn'?'triangle-alert':'clipboard-check',18)}</span><div><span class="check-type">${c.type}</span><h3>${esc(c.title)}</h3><p>${esc(c.detail)}</p></div></article>`;}
function showChecks(id){const list=checks(state).filter(c=>!id||c.ids.includes(id));showDialog(id?`${partFor(state,id).short} · checks`:'Assembly checks',`<p class="dialog-intro">These checks use the un-exploded layout. “No collisions” is not an approval to manufacture or power the device.</p><div class="dialog-checks">${list.map(checkCard).join('')}</div>`);}

