function customDialog(){
 showDialog('Add a component',`<p class="dialog-intro">Add any part using its dimensions. You can map contacts and cables after adding it.</p><form id="custom-form"><label>Name<input name="name" required maxlength="100" placeholder="e.g. CO₂ sensor module"></label><label>Product / purchase link<input name="url" type="url" placeholder="https://…"></label><label>Component type<select name="kind">${['board','chip','camera','battery','screen','motor','connector','antenna','other'].map(kind=>`<option>${kind}</option>`).join('')}</select></label><label>Interface / supply<input name="interface" maxlength="250" placeholder="e.g. I²C, 3.3 V (to verify)"></label><div class="triple-fields">${['Width','Height','Depth'].map((a,i)=>`<label>${a} · mm<input name="d${i}" required type="number" step="0.1" min="0.1" max="1000" value="20"></label>`).join('')}</div><label class="checkbox-label"><input name="owned" type="checkbox"> I have this part</label><button class="button primary full" type="submit">Add to assembly</button></form>`);
 $('#custom-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),id='custom-'+crypto.randomUUID(),url=form.get('url').trim();if(url&&!safeUrl(url)){toast('Use a full http(s) product link.');return;}if(state.custom.length>=40||state.instances.length>=60){toast('This project has reached its part limit.');return;}
 mutate(()=>{const part={id,name:form.get('name').trim(),short:form.get('name').trim(),interface:form.get('interface').trim()||'Unspecified',owned:form.get('owned')==='on',dimensions:[0,1,2].map(n=>+form.get('d'+n)),category:'Custom',kind:form.get('kind'),color:'#124567',quantity:1,confidence:'estimate',dimensionNote:'User-entered envelope. Verify measurements, protrusions and tolerances.',summary:'Custom component. Electrical compatibility has not been assessed.',placement:'Check mounting, connector access and clearance.',electrical:'Review voltage, pin allocation and firmware before wiring.',sources:[],purchaseLinks:url?[['View product',url]]:[],photo:'User-added component',ports:[],tags:['Custom']};state.custom.push(part);state.instances.push({id,dimensions:[...part.dimensions],position:nextPosition(state,part.dimensions),rotation:[0,0,0]});selected=id;inspectorOpen=true;});$('#dialog').close();toast('Component added. Use Pins & internals to add contacts.');};
}
function enclosureDialog(){showDialog('Proposed enclosure interior',`<p class="dialog-intro">This is the usable interior volume, not a manufactured case. Allow additional wall thickness, fasteners, cable bends, pouch clearance and openings.</p><form id="enclosure-form"><div class="triple-fields">${['Width · X','Height · Y','Depth · Z'].map((a,i)=>`<label>${a} · mm<input name="e${i}" type="number" min="1" max="2000" step="1" value="${state.enclosure[i]}" required></label>`).join('')}</div><button class="button primary full" type="submit">Update interior</button></form>`);$('#enclosure-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);mutate(()=>state.enclosure=[0,1,2].map(i=>+f.get('e'+i)));$('#dialog').close();};}
function layoutsDialog(){
  let snapshots=[];try{snapshots=JSON.parse(localStorage.getItem(STORAGE_KEY+'.snapshots')||'[]');if(!Array.isArray(snapshots))snapshots=[];}catch{}
  showDialog('Layouts & snapshots',`<p class="dialog-intro">Save a variation or import a project. Use a sample layout below or choose a starter from New project.</p><details class="detail-section"><summary>Sample assemblies</summary><div class="preset-grid"><button data-preset="compact">${icon('panel-top',26)}<strong>Compact study</strong><small>Stacked battery · strip candidate</small></button><button data-preset="bench">${icon('radio',26)}<strong>Bench prototype</strong><small>Current carrier · external antenna</small></button><button data-preset="wide">${icon('columns-2',26)}<strong>Side by side</strong><small>Less stacking · wider footprint</small></button></div></details><button class="button full" id="save-snapshot">${icon('bookmark-plus',16)} Save current layout snapshot</button><h3 class="snapshot-heading">Saved in this browser</h3><div class="snapshot-list">${snapshots.length?snapshots.map((s,i)=>`<button data-snapshot="${i}"><span><strong>${esc(s.name)}</strong><small>${new Date(s.updatedAt).toLocaleString()}</small></span>${icon('arrow-right',16)}</button>`).join(''):'<p class="hint">No snapshots yet.</p>'}</div><div class="dialog-divider"></div><button class="button full" id="import-project">${icon('upload',16)} Import a shared project (.json)</button>`);
  $$('[data-preset]').forEach(b=>b.onclick=()=>{const p=b.dataset.preset;mutate(()=>{const base=defaultState(p==='bench'?'bench':'compact');if(p==='wide'){base.name='Side-by-side study';base.enclosure=[150,38,122];base.instances.find(i=>i.id==='battery').position=[-36,4.5,6];moveInstance(base,'expansion',[34,8,10],[0,0,0]);base.instances.find(i=>i.id==='thermal').position=[20,15,-48];base.instances.find(i=>i.id==='strip').position=[-35,19,-48];}Object.assign(state,{name:base.name,preset:p,instances:base.instances,enclosure:base.enclosure,lockCore:true,connections:seedConnections(p)});});viewer?.setExplode(0);$('#explode').value=0;$('#explode-value').textContent='0%';$('#dialog').close();toast('Layout loaded');});
  $('#save-snapshot').onclick=()=>{try{snapshots.push(clone(state));localStorage.setItem(STORAGE_KEY+'.snapshots',JSON.stringify(snapshots.slice(-20)));toast('Snapshot saved');layoutsDialog();}catch{toast('Could not save snapshot. Export the project instead.');}};
  $$('[data-snapshot]').forEach(b=>b.onclick=()=>{try{const next=validateState(snapshots[+b.dataset.snapshot]);mutate(()=>state=next);$('#dialog').close();}catch{toast('This snapshot could not be read.');}});
  $('#import-project').onclick=()=>$('#import-input').click();
}

