// Compare presentation only, preserving model materials and saved layouts.
$$('[data-material-color]').forEach(button=>button.onclick=()=>{
  $('#viewport').classList.toggle('is-monochrome',button.dataset.materialColor==='mono');
  $$('[data-material-color]').forEach(option=>{
    const active=option===button;option.classList.toggle('active',active);option.setAttribute('aria-pressed',String(active));
  });
});
$$('[data-view]').forEach(b=>b.onclick=()=>{viewer?.setView(b.dataset.view);$$('[data-view]').forEach(el=>el.classList.toggle('active',el===b));});$('#fit-view').onclick=()=>viewer?.setView('iso');$('#explode').oninput=e=>{viewer?.setExplode(+e.target.value/100);$('#explode-value').textContent=e.target.value+'%';};
for(const [id,prop]of [['labels-btn','showLabels'],['wires-btn','showWires']])$('#'+id).onclick=()=>{if(!viewer)return;viewer[prop]=!viewer[prop];$('#'+id).classList.toggle('active',viewer[prop]);$('#'+id).setAttribute('aria-pressed',viewer[prop]);if(prop==='showWires')viewer.makeWires();};$('#shell-btn').onclick=()=>mutate(()=>state.enclosureVisible=!state.enclosureVisible);
window.addEventListener('resize',()=>requestAnimationFrame(drawConnections));new ResizeObserver(()=>requestAnimationFrame(drawConnections)).observe($('#wire-map'));
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('#dialog').open)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(page==='assembly'&&!e.metaKey&&!e.ctrlKey){if(e.key==='g')$('[data-mode="translate"]').click();if(e.key==='r')$('[data-mode="rotate"]').click();if(e.key==='Escape'){pendingPort=null;$('[data-mode="inspect"]').click();render();}}});
render();if(restoreMessage)toast(restoreMessage);

if(new URLSearchParams(location.search).get('guide')==='lcd')lcdCableGuide();

if(new URLSearchParams(location.search).get('guide')==='haptics')hapticGuide();

let product;
mountProduct({
 get route(){return route;},get continueUrl(){return continueUrl;},get storageKey(){return STORAGE_KEY;},getStorageKey:()=>STORAGE_KEY,isBuilding:()=>building,getSelected:()=>active(selected)?selected:null,
 applyAdjustment:(proposal,base)=>{if(JSON.stringify(state)!==base)throw Error('The assembly changed. Ask codex to refresh this proposal before applying.');const next=applyAdjustments(state,proposal);mutate(()=>state=next);},
 startProject:()=>{
  route={id:'build-'+crypto.randomUUID(),generated:true};route.key=route.id;STORAGE_KEY=BASE_STORAGE_KEY+':'+route.key;
  window.history.pushState({},'',projectUrl(route.id));continueUrl=projectUrl(route.id);
  try{localStorage.setItem(BASE_STORAGE_KEY+'.lastRoute',continueUrl);}catch{}
  state=emptyProject('New project');state.build={status:'running'};building=true;history=[];future=[];selected=null;inspectorOpen=false;page='assembly';pendingPort=null;viewer?.setMode('inspect');persist();render();
  document.dispatchEvent(new Event('phygital:project'));
 },
 draft:next=>{state=validateState(next);state.build={status:'running'};persist();render();},
 model:(id,result)=>{const part=state.custom.find(p=>p.id===id);if(!part)return;Object.assign(part,result);viewer?.invalidate(id);persist();render();},
 endBuild:status=>{building=false;state.build={status};persist();render();},
 getState:()=>state,toast,dialog:showDialog,custom:customDialog,register:value=>product=value,
 replace:(next,id)=>{const clean=validateState(next);mutate(()=>{state=clean;selected=id||clean.instances[0]?.id||null;inspectorOpen=false;page='assembly';pendingPort=null;});},
 addLibrary:async id=>{mutate(()=>{if(state.instances.length>=60||state.custom.length>=40){toast('This project has reached its part limit.');return;}selected=libraryPart(state,id);});if(viewer){await viewer.sync(state,selected);viewer.setView('iso');}},
 resize:()=>viewer?.resize(),
 fit:async()=>{if(viewer){await viewer.sync(state,selected);viewer.resize();viewer.setView('iso');}}
});

window.addEventListener('popstate',()=>location.reload());
